
function searchTitles(q, titles){
  if(!q || typeof q !== 'string') return [];
  var needle = q.toLowerCase().trim();
  if(!needle) return [];
  var out = [];
  for(var i=0;i<titles.length && out.length<10;i++){
    var row = titles[i];
    var hay = ((row[0]||'')+' '+(row[1]||'')).toLowerCase();
    if(hay.indexOf(needle) !== -1) out.push(row[1] + ' (' + row[0] + ')');
  }
  return out;
}

function haversine(lat1, lon1, lat2, lon2){
  var a=Number(lat1), b=Number(lon1), c=Number(lat2), d=Number(lon2);
  if(!isFinite(a)||!isFinite(b)||!isFinite(c)||!isFinite(d)) return {error:'Enter numbers for all four boxes.'};
  if(a<-90||a>90||c<-90||c>90) return {error:'Latitudes must be between -90 and 90.'};
  if(b<-180||b>180||d<-180||d>180) return {error:'Longitudes must be between -180 and 180.'};
  var R=6371, p=Math.PI/180;
  var dl=(c-a)*p, dn=(d-b)*p;
  var h=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(a*p)*Math.cos(c*p)*Math.sin(dn/2)*Math.sin(dn/2);
  var km=2*R*Math.asin(Math.sqrt(h));
  return {km:Math.round(km*100)/100, miles:Math.round(km*0.621371*100)/100};
}
